    public sealed class ArenaPickupDefinition {
        public readonly string Id,Name,Effect,Hero; public readonly int Tier,MinLevel; public readonly float Value,Duration;
        public ArenaPickupDefinition(string id,string name,string effect,string hero,int tier,int level,float value,float duration){Id=id;Name=name;Effect=effect;Hero=hero;Tier=tier;MinLevel=level;Value=value;Duration=duration;}
    }
    public sealed class ArenaFieldDrop {
        public readonly int Id;public readonly ArenaPickupDefinition Item;public readonly Vector2 Position;public readonly ArenaTeam Team;public readonly float SpawnedAt;
        internal ArenaFieldDrop(int id,ArenaPickupDefinition item,Vector2 pos,ArenaTeam team,float now){Id=id;Item=item;Position=pos;Team=team;SpawnedAt=now;}
    }
